"use client"

import type { JSX } from "react"

import {
  CreditBalance,
  type CreditBalanceProps,
} from "@/components/mockups/credit-balance"
import {
  DailyUsageTable,
  type DailyUsageRow,
} from "@/components/mockups/daily-usage-table"
import {
  LivepeerAgentPromoCards,
  type LivepeerAgentPromoPlan,
} from "@/components/mockups/livepeer-agent-promo-cards"
import {
  ResourceUsageTable,
  type ResourceUsageRow,
} from "@/components/mockups/resource-usage-table"
import {
  UsageMetrics,
  type UsageMetric,
} from "@/components/mockups/usage-metrics"
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs"

export type UsageWorkspaceContent = {
  overviewTabLabel: string
  activityTabLabel: string
  upgradeTitle: string
  upgradeDescription: string
  dailyUsageTitle: string
  dailyUsageEmptyMessage: string
  resourceUsageTitle: string
  resourceUsageEmptyMessage: string
}

export type UsageWorkspaceProps = {
  content: UsageWorkspaceContent
  balance: CreditBalanceProps
  metrics: readonly UsageMetric[]
  dailyRows: readonly DailyUsageRow[]
  resourceRows: readonly ResourceUsageRow[]
  plans: readonly LivepeerAgentPromoPlan[]
  onPlanSelect?: (plan: LivepeerAgentPromoPlan) => void
}

export function UsageWorkspace(props: UsageWorkspaceProps): JSX.Element {
  const {
    content,
    balance,
    metrics,
    dailyRows,
    resourceRows,
    plans,
    onPlanSelect,
  } = props

  return (
    <Tabs defaultValue="overview" className="gap-8">
      <TabsList
        variant="line"
        className="w-full justify-start overflow-x-auto border-b px-0 pb-1"
      >
        <TabsTrigger value="overview" className="flex-none">
          {content.overviewTabLabel}
        </TabsTrigger>
        <TabsTrigger value="activity" className="flex-none">
          {content.activityTabLabel}
        </TabsTrigger>
      </TabsList>
      <TabsContent value="overview">
        <div className="flex flex-col gap-10">
          <CreditBalance {...balance} />
          <section>
            <h2 className="font-sans text-2xl font-medium tracking-tight">
              {content.upgradeTitle}
            </h2>
            <p className="mt-2 max-w-2xl text-sm leading-relaxed text-muted-foreground">
              {content.upgradeDescription}
            </p>
            <div className="mt-6">
              <LivepeerAgentPromoCards
                plans={plans}
                onPlanSelect={onPlanSelect}
              />
            </div>
          </section>
        </div>
      </TabsContent>
      <TabsContent value="activity">
        <div className="flex flex-col gap-10">
          <section>
            <UsageMetrics metrics={metrics} />
          </section>
          <DailyUsageTable
            title={content.dailyUsageTitle}
            rows={dailyRows}
            emptyMessage={content.dailyUsageEmptyMessage}
          />
          <ResourceUsageTable
            title={content.resourceUsageTitle}
            rows={resourceRows}
            emptyMessage={content.resourceUsageEmptyMessage}
          />
        </div>
      </TabsContent>
    </Tabs>
  )
}

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"

export type DailyUsageRow = {
  id: string
  date: string
  workflowRuns: string
  compute: string
  credits: string
}

export type DailyUsageTableProps = {
  title: string
  rows: readonly DailyUsageRow[]
  emptyMessage: string
}

export function DailyUsageTable({
  title,
  rows,
  emptyMessage,
}: DailyUsageTableProps) {
  return (
    <section className="flex flex-col gap-3">
      <h2 className="font-sans text-sm font-medium">{title}</h2>
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Date</TableHead>
            <TableHead>Workflow runs</TableHead>
            <TableHead>Compute</TableHead>
            <TableHead className="text-right">Credits</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.length === 0 ? (
            <TableRow>
              <TableCell
                colSpan={4}
                className="h-24 text-center text-muted-foreground"
              >
                {emptyMessage}
              </TableCell>
            </TableRow>
          ) : (
            rows.map((day) => (
              <TableRow key={day.id}>
                <TableCell className="font-medium">{day.date}</TableCell>
                <TableCell className="font-sans text-xs tabular-nums">
                  {day.workflowRuns}
                </TableCell>
                <TableCell className="font-sans text-xs tabular-nums">
                  {day.compute}
                </TableCell>
                <TableCell className="text-right font-sans text-xs tabular-nums">
                  {day.credits}
                </TableCell>
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
    </section>
  )
}

"use client"

import type { MouseEventHandler } from "react"
import { ArrowRightIcon } from "lucide-react"

import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"

export type LivepeerAgentPromoPlan = {
  id: string
  name: string
  credits: string
  creditsLabel: string
  description: string
  ctaLabel: string
  href: string
  recommendedLabel?: string
}

export type LivepeerAgentPromoCardsProps = {
  plans: readonly LivepeerAgentPromoPlan[]
  onPlanSelect?: (plan: LivepeerAgentPromoPlan) => void
}

export function LivepeerAgentPromoCards({
  plans,
  onPlanSelect,
}: LivepeerAgentPromoCardsProps) {
  return (
    <div className="grid gap-4 md:grid-cols-2">
      {plans.map((plan) => {
        const recommended = Boolean(plan.recommendedLabel)
        const handleClick: MouseEventHandler<HTMLAnchorElement> | undefined =
          onPlanSelect ? () => onPlanSelect(plan) : undefined

        return (
          <div
            key={plan.id}
            className={
              recommended
                ? "relative flex min-h-64 flex-col rounded-sm border border-emerald-500 p-6"
                : "flex min-h-64 flex-col rounded-sm border p-6"
            }
          >
            {plan.recommendedLabel ? (
              <Badge className="absolute top-0 right-6 -translate-y-1/2 bg-emerald-500 text-white">
                {plan.recommendedLabel}
              </Badge>
            ) : null}
            <p
              className={
                recommended
                  ? "text-sm font-medium text-emerald-700"
                  : "text-sm font-medium text-muted-foreground"
              }
            >
              {plan.name}
            </p>
            <p className="mt-5 text-4xl font-medium tracking-tight tabular-nums">
              {plan.credits}{" "}
              <span className="text-lg font-normal text-muted-foreground">
                {plan.creditsLabel}
              </span>
            </p>
            <p className="mt-4 text-sm text-muted-foreground">
              {plan.description}
            </p>
            <Button
              variant={recommended ? "secondary" : "outline"}
              size="lg"
              nativeButton={false}
              render={<a href={plan.href} onClick={handleClick} />}
              className={
                recommended
                  ? "mt-auto h-16 w-full rounded-sm border border-emerald-500 bg-emerald-500 px-4 text-white hover:bg-emerald-500"
                  : "mt-auto h-16 w-full rounded-sm px-4"
              }
              style={
                recommended
                  ? {
                      backgroundImage:
                        "linear-gradient(160deg, color(display-p3 0.04 0.74 0.49) 0%, color(display-p3 0.04 0.74 0.49) 32%, color(display-p3 0.02 0.58 0.36) 100%)",
                    }
                  : undefined
              }
            >
              {plan.ctaLabel}
              <ArrowRightIcon aria-hidden="true" />
            </Button>
          </div>
        )
      })}
    </div>
  )
}

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"

export type ResourceUsageRow = {
  id: string
  resource: string
  type: string
  usage: string
  credits: string
}

export type ResourceUsageTableProps = {
  title: string
  rows: readonly ResourceUsageRow[]
  emptyMessage: string
}

export function ResourceUsageTable({
  title,
  rows,
  emptyMessage,
}: ResourceUsageTableProps) {
  return (
    <section className="flex flex-col gap-3">
      <h2 className="font-sans text-sm font-medium">{title}</h2>
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Resource</TableHead>
            <TableHead>Type</TableHead>
            <TableHead>Usage</TableHead>
            <TableHead className="text-right">Credits</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.length === 0 ? (
            <TableRow>
              <TableCell
                colSpan={4}
                className="h-24 text-center text-muted-foreground"
              >
                {emptyMessage}
              </TableCell>
            </TableRow>
          ) : (
            rows.map((resource) => (
              <TableRow key={resource.id}>
                <TableCell className="font-mono text-xs font-medium">
                  {resource.resource}
                </TableCell>
                <TableCell>{resource.type}</TableCell>
                <TableCell className="font-sans text-xs tabular-nums">
                  {resource.usage}
                </TableCell>
                <TableCell className="text-right font-sans text-xs tabular-nums">
                  {resource.credits}
                </TableCell>
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
    </section>
  )
}

import {
  Card,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card"

export type UsageMetric = {
  label: string
  value: string
}

export type UsageMetricsProps = {
  metrics: readonly UsageMetric[]
}

export function UsageMetrics({ metrics }: UsageMetricsProps) {
  return (
    <div className="grid gap-3 sm:grid-cols-2">
      {metrics.map((metric) => (
        <Card key={metric.label} variant="metric">
          <CardHeader>
            <CardDescription>{metric.label}</CardDescription>
            <CardTitle className="font-sans text-3xl leading-none font-medium tracking-tight tabular-nums">
              {metric.value}
            </CardTitle>
          </CardHeader>
        </Card>
      ))}
    </div>
  )
}
